#include "save/GeneratorCompatibility.hpp"
namespace elysium::save {bool GeneratorCompatibilityRegistry::registerGenerator(GeneratorIdentity g){if(!g.version||!g.fingerprint)return false;generators_[g.version]=g;return true;}bool GeneratorCompatibilityRegistry::registerMigration(MigrationStep s){if(!s.from.version||!s.to.version||!s.transform||s.from.version==s.to.version)return false;migrations_[s.from.version]=std::move(s);return true;}CompatibilityResult GeneratorCompatibilityRegistry::check(const BaselineStamp&s)const{auto i=generators_.find(s.generator.version);if(i==generators_.end())return migrations_.contains(s.generator.version)?CompatibilityResult::MigrationRequired:CompatibilityResult::MissingGenerator;if(i->second.fingerprint!=s.generator.fingerprint)return CompatibilityResult::FingerprintMismatch;return CompatibilityResult::ExactMatch;}CompatibilityResult GeneratorCompatibilityRegistry::migrate(BaselineStamp&s,std::vector<std::uint8_t>&payload,GeneratorIdentity target)const{if(s.generator==target)return check(s);for(std::size_t guard=0;guard<generators_.size()+migrations_.size()+1&&s.generator.version!=target.version;++guard){auto i=migrations_.find(s.generator.version);if(i==migrations_.end()||i->second.from.fingerprint!=s.generator.fingerprint)return CompatibilityResult::MigrationUnavailable;auto copy=s;auto bytes=payload;if(!i->second.transform(copy,bytes))return CompatibilityResult::MigrationUnavailable;copy.generator=i->second.to;s=copy;payload=std::move(bytes);}if(s.generator.version!=target.version)return CompatibilityResult::MigrationUnavailable;return s.generator.fingerprint==target.fingerprint?CompatibilityResult::ExactMatch:CompatibilityResult::FingerprintMismatch;}
} // namespace elysium::save
